// =====================================================================
//  PRACTICE WATCHDOG - SETTINGS  (the only node you normally edit)
// =====================================================================
const CONFIG = {
  // Date the checks run "as of". Keep '2026-09-23' for the capstone demo data.
  // Set to '' for live use and the workflow will use today's date (IST).
  asOfDate: '2026-09-23',

  exportFileId: '11tt6-zHXSCNNexn3xpIRM82HF6wOdDs4',   // Google Drive file ID of the practice-software export
  partnerEmail: 'tanvorashah@gmail.com',              // who receives the daily digest
  firmName: 'Demo & Associates, Chartered Accountants',

  thresholds: {
    dueSoonDays: 7,            // look-ahead window for deadlines and workload
    lowProgressPct: 50,        // due soon, but less than this % of budgeted hours logged
    overrunTolerancePct: 10,   // flag when actual hours exceed budget by more than this %
    longDayHrs: 11,            // flag anyone logging more than this in a single day
    weeklyOffDays: [0],        // 0 = Sunday (CA offices usually work Saturdays)
    completedStatuses: ['Completed', 'Done', 'Filed', 'Closed']
  },

  // ----- COLUMN MAPPING -----------------------------------------------
  // Left side = field the watchdog uses. Right side = column header in YOUR export.
  // To connect a different practice software, change only the right-hand values.
  columnMap: {
    staff:     { staff_id: 'staff_id', staff_name: 'staff_name', role: 'role', email: 'email',
                 daily_capacity_hrs: 'daily_capacity_hrs' },
    tasks:     { task_id: 'task_id', client_name: 'client_name', work_type: 'work_type',
                 description: 'description', assignee_id: 'assignee_id', reviewer_id: 'reviewer_id',
                 due_date: 'due_date', budget_hrs: 'budget_hrs', status: 'status', completed_on: 'completed_on' },
    timesheet: { entry_id: 'entry_id', date: 'date', staff_id: 'staff_id', task_id: 'task_id',
                 client_name: 'client_name', hours: 'hours', narration: 'narration' },
    evidence:  { evidence_id: 'evidence_id', task_id: 'task_id', evidence_type: 'evidence_type',
                 reference_no: 'reference_no', evidence_date: 'evidence_date', source: 'source' }
  }
};

if (!CONFIG.asOfDate) CONFIG.asOfDate = $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd');
return [{ json: CONFIG }];

// ============================================================================
// WATCHDOG RULE ENGINE - deterministic checks on the practice-software export
// ============================================================================
function runChecks(raw, cfg) {
  // ---------- 1. remap columns from the practice-software export ----------
  const remap = (rows, map) => rows.map(r => {
    const o = {};
    for (const [generic, source] of Object.entries(map)) o[generic] = r[source];
    return o;
  });
  const parseDate = v => {
    if (v === undefined || v === null || v === '') return null;
    if (typeof v === 'number') {                               // Excel serial date
      const d = new Date(Date.UTC(1899, 11, 30) + v * 86400000);
      return d.toISOString().slice(0, 10);
    }
    const s = String(v).trim();
    let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);               // 2026-09-23
    if (m) return `${m[1]}-${m[2]}-${m[3]}`;
    m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);  // 23/09/2026 or 23-09-2026 (Indian dd/mm)
    if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
    const d = new Date(s);
    return isNaN(d) ? null : d.toISOString().slice(0, 10);
  };
  const num = v => { const n = parseFloat(String(v ?? '').replace(/,/g, '')); return isNaN(n) ? 0 : n; };
  const str = v => (v === undefined || v === null) ? '' : String(v).trim();
  const M = cfg.columnMap;

  const staff = remap(raw.staff, M.staff).map(s => ({ ...s, staff_id: str(s.staff_id), daily_capacity_hrs: num(s.daily_capacity_hrs) || 8 }));
  const tasks = remap(raw.tasks, M.tasks).map(t => ({
    ...t, task_id: str(t.task_id), assignee_id: str(t.assignee_id), reviewer_id: str(t.reviewer_id),
    due_date: parseDate(t.due_date), completed_on: parseDate(t.completed_on), budget_hrs: num(t.budget_hrs),
    status: str(t.status) }));
  const ts = remap(raw.timesheet, M.timesheet).map(e => ({
    ...e, entry_id: str(e.entry_id), staff_id: str(e.staff_id), task_id: str(e.task_id),
    date: parseDate(e.date), hours: num(e.hours), narration: str(e.narration) }));
  const ev = remap(raw.evidence, M.evidence).map(e => ({ ...e, task_id: str(e.task_id) }));

  // ---------- 2. helpers ----------
  const T = cfg.thresholds;
  const asOf = cfg.asOfDate;
  const dayDiff = (a, b) => Math.round((Date.parse(a) - Date.parse(b)) / 86400000);
  const isDone = t => T.completedStatuses.map(x => x.toLowerCase()).includes(t.status.toLowerCase());
  const staffBy = Object.fromEntries(staff.map(s => [s.staff_id, s]));
  const taskBy = Object.fromEntries(tasks.map(t => [t.task_id, t]));
  const name = id => staffBy[id]?.staff_name || id || '-';
  const logged = {};
  ts.forEach(e => { logged[e.task_id] = (logged[e.task_id] || 0) + e.hours; });
  const evBy = {};
  ev.forEach(e => { (evBy[e.task_id] = evBy[e.task_id] || []).push(e); });

  const findings = [];
  const add = (rule, severity, f) => findings.push({ rule, severity, detector: 'Rule', ...f });
  const tInfo = t => ({ task_id: t.task_id, client: t.client_name, task: `${t.work_type} - ${t.description}`,
                        staff_id: t.assignee_id, staff: name(t.assignee_id), due_date: t.due_date });

  // ---------- 3. task-level checks ----------
  for (const t of tasks) {
    const hrs = +(logged[t.task_id] || 0).toFixed(1);
    const daysLeft = t.due_date ? dayDiff(t.due_date, asOf) : null;
    const pct = t.budget_hrs ? Math.round(hrs / t.budget_hrs * 100) : 0;

    if (!isDone(t) && !evBy[t.task_id] && daysLeft !== null && daysLeft < 0)
      add('OVERDUE', 'High', { ...tInfo(t), detail: `Due ${t.due_date} (${-daysLeft} day(s) ago), status "${t.status}", ${hrs} hrs logged.` });

    if (!isDone(t) && daysLeft !== null && daysLeft >= 0 && daysLeft <= T.dueSoonDays && pct < T.lowProgressPct)
      add('DUE_SOON_LOW_PROGRESS', 'High', { ...tInfo(t), detail: `Due in ${daysLeft} day(s); only ${hrs} of ${t.budget_hrs} budgeted hrs logged (${pct}%).` });

    if (t.budget_hrs && hrs > t.budget_hrs * (1 + T.overrunTolerancePct / 100))
      add('BUDGET_OVERRUN', 'Medium', { ...tInfo(t), detail: `${hrs} hrs logged vs ${t.budget_hrs} budgeted (${pct}%).` });

    if (isDone(t) && !evBy[t.task_id])
      add('COMPLETED_NO_EVIDENCE', 'High', { ...tInfo(t), detail: `Marked "${t.status}" on ${t.completed_on || '?'} but no acknowledgement / ARN / UDIN found.` });

    if (!isDone(t) && evBy[t.task_id])
      add('EVIDENCE_BUT_OPEN', 'Low', { ...tInfo(t), detail: `Evidence ${evBy[t.task_id].map(e => `${e.evidence_type} ${e.reference_no}`).join(', ')} received, but task still "${t.status}". Update the status.` });
  }

  // ---------- 4. timesheet-level checks ----------
  const seen = {};
  const dayTotals = {};
  for (const e of ts) {
    const t = taskBy[e.task_id];
    const base = { entry_id: e.entry_id, date: e.date, staff_id: e.staff_id, staff: name(e.staff_id),
                   task_id: e.task_id, client: t ? t.client_name : (e.client_name || '-'),
                   task: t ? `${t.work_type} - ${t.description}` : '-' };
    if (!t) {
      add('UNKNOWN_TASK', 'High', { ...base, detail: `${e.hours} hrs booked to task "${e.task_id}", which is not in the task master.` });
    } else {
      if (t.completed_on && e.date > t.completed_on)
        add('HOURS_AFTER_COMPLETION', 'Medium', { ...base, detail: `${e.hours} hrs on ${e.date}, after the task was completed on ${t.completed_on}.` });
      if (e.staff_id !== t.assignee_id && e.staff_id !== t.reviewer_id)
        add('NOT_ASSIGNED', 'Medium', { ...base, detail: `${e.hours} hrs booked by ${name(e.staff_id)}; task is assigned to ${name(t.assignee_id)} (reviewer ${name(t.reviewer_id)}).` });
    }
    const k = [e.staff_id, e.date, e.task_id, e.hours, e.narration.toLowerCase()].join('|');
    if (seen[k]) add('DUPLICATE_ENTRY', 'Medium', { ...base, detail: `Identical to entry ${seen[k]} (${e.hours} hrs, same narration).` });
    else seen[k] = e.entry_id;
    const dk = e.staff_id + '|' + e.date;
    dayTotals[dk] = (dayTotals[dk] || 0) + e.hours;
  }
  for (const [dk, h] of Object.entries(dayTotals)) {
    if (h > T.longDayHrs) {
      const [sid, date] = dk.split('|');
      add('LONG_DAY', 'Low', { staff_id: sid, staff: name(sid), date, detail: `${h} hrs logged in one day (limit ${T.longDayHrs}). Check for padding or burnout.` });
    }
  }

  // ---------- 5. workload / capacity (next N days) ----------
  const horizonEnd = new Date(Date.parse(asOf) + T.dueSoonDays * 86400000).toISOString().slice(0, 10);
  let workdays = 0;
  for (let d = 1; d <= T.dueSoonDays; d++) {
    const wd = new Date(Date.parse(asOf) + d * 86400000).getUTCDay();
    if (!T.weeklyOffDays.includes(wd)) workdays++;
  }
  const workload = staff.map(s => {
    const open = tasks.filter(t => t.assignee_id === s.staff_id && !isDone(t) && t.due_date && t.due_date <= horizonEnd);
    const remaining = open.reduce((a, t) => a + Math.max(t.budget_hrs - (logged[t.task_id] || 0), 0), 0);
    const capacity = s.daily_capacity_hrs * workdays;
    const periodHrs = ts.filter(e => e.staff_id === s.staff_id).reduce((a, e) => a + e.hours, 0);
    return { staff_id: s.staff_id, staff: s.staff_name, role: s.role,
             due_next_period_hrs: +remaining.toFixed(1), capacity_hrs: capacity,
             utilisation_pct: capacity ? Math.round(remaining / capacity * 100) : 0,
             spare_hrs: +Math.max(capacity - remaining, 0).toFixed(1),
             hrs_logged_in_export: +periodHrs.toFixed(1),
             open_tasks_due: open.map(t => `${t.task_id} ${t.client_name} (${t.work_type}, due ${t.due_date})`) };
  });
  for (const w of workload) {
    if (w.due_next_period_hrs > w.capacity_hrs)
      add('OVERLOAD', 'Medium', { staff_id: w.staff_id, staff: w.staff,
        detail: `${w.due_next_period_hrs} hrs of work due by ${horizonEnd} vs ${w.capacity_hrs} hrs capacity (${w.utilisation_pct}%). Tasks: ${w.open_tasks_due.join('; ')}.` });
  }

  // ---------- 6. client budget vs actual ----------
  const clients = {};
  for (const t of tasks) {
    const c = clients[t.client_name] = clients[t.client_name] || { client: t.client_name, budget_hrs: 0, actual_hrs: 0 };
    c.budget_hrs += t.budget_hrs; c.actual_hrs += logged[t.task_id] || 0;
  }
  const clientSummary = Object.values(clients).map(c => ({ ...c, actual_hrs: +c.actual_hrs.toFixed(1),
    pct: c.budget_hrs ? Math.round(c.actual_hrs / c.budget_hrs * 100) : 0 })).sort((a, b) => b.pct - a.pct);

  // ---------- 7. payload for the AI narration reviewer ----------
  const aiEntries = ts.filter(e => taskBy[e.task_id]).map(e => ({
    entry_id: e.entry_id, staff: name(e.staff_id), hours: e.hours,
    task_type: taskBy[e.task_id].work_type, task_description: taskBy[e.task_id].description,
    narration: e.narration }));

  return {
    asOfDate: asOf, horizonEnd,
    stats: { staff: staff.length, tasks: tasks.length, timesheetEntries: ts.length, evidence: ev.length,
             totalHours: +ts.reduce((a, e) => a + e.hours, 0).toFixed(1),
             openTasks: tasks.filter(t => !isDone(t)).length },
    ruleFindings: findings, workload, clientSummary, aiEntries,
    entryIndex: Object.fromEntries(ts.map(e => [e.entry_id, { date: e.date, staff_id: e.staff_id, staff: name(e.staff_id),
      task_id: e.task_id, client: taskBy[e.task_id]?.client_name || e.client_name, hours: e.hours, narration: e.narration,
      task: taskBy[e.task_id] ? `${taskBy[e.task_id].work_type} - ${taskBy[e.task_id].description}` : '-' }]))
  };
}

// ---------- run ----------
const cfg = $('Watchdog Settings').first().json;
const raw = {
  staff:     $('Read Staff Sheet').all().map(i => i.json),
  tasks:     $('Read Tasks Sheet').all().map(i => i.json),
  timesheet: $('Read Timesheet Sheet').all().map(i => i.json),
  evidence:  $('Read Evidence Sheet').all().map(i => i.json)
};
return [{ json: runChecks(raw, cfg) }];

// Merge the AI reviewer's flags with the rule-engine findings.
const base = $('Run Rule Checks').first().json;
let text = String($json.text ?? $json.output ?? '');
text = text.replace(/```(?:json)?/gi, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
let aiFlags = [], aiError = null;
try {
  const parsed = JSON.parse(text.slice(s, e + 1));
  aiFlags = Array.isArray(parsed.flags) ? parsed.flags : [];
} catch (err) {
  aiError = 'AI reviewer output could not be parsed; narration checks skipped this run.';
}

const allowed = { VAGUE_NARRATION: 'Low', NARRATION_MISMATCH: 'Medium' };
const aiFindings = [];
const seen = new Set();
for (const f of aiFlags) {
  const entry = base.entryIndex[f.entry_id];
  const rule = String(f.issue || '').toUpperCase();
  if (!entry || !allowed[rule] || seen.has(f.entry_id + rule)) continue;   // ignore hallucinated ids
  seen.add(f.entry_id + rule);
  aiFindings.push({
    rule, severity: allowed[rule], detector: 'AI', entry_id: f.entry_id,
    date: entry.date, staff_id: entry.staff_id, staff: entry.staff, task_id: entry.task_id,
    client: entry.client, task: entry.task,
    detail: `${entry.hours} hrs: "${entry.narration}". ${f.reason || ''}`.trim()
  });
}

const rank = { High: 0, Medium: 1, Low: 2 };
const findings = [...base.ruleFindings, ...aiFindings]
  .sort((a, b) => rank[a.severity] - rank[b.severity] || a.rule.localeCompare(b.rule));
const count = sev => findings.filter(f => f.severity === sev).length;
const byRule = {};
findings.forEach(f => { byRule[f.rule] = (byRule[f.rule] || 0) + 1; });

return [{ json: {
  asOfDate: base.asOfDate, horizonEnd: base.horizonEnd, stats: base.stats,
  findings, byRule, aiError,
  counts: { total: findings.length, high: count('High'), medium: count('Medium'), low: count('Low'),
            ai: aiFindings.length, rule: base.ruleFindings.length },
  workload: base.workload, clientSummary: base.clientSummary
} }];

