// Build the partner digest email (HTML).
const d = $('Combine Findings').first().json;
const cfg = $('Watchdog Settings').first().json;
let brief = String($json.text ?? $json.output ?? '').replace(/```(?:html)?/gi, '').trim();
if (!brief) brief = '<p>(AI briefing unavailable this run. See the detailed findings below.)</p>';

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = r => r.replace(/_/g, ' ').toLowerCase().replace(/^./, c => c.toUpperCase());
const colour = { High: '#b42318', Medium: '#b54708', Low: '#475467' };
const bg = { High: '#fef3f2', Medium: '#fffaeb', Low: '#f2f4f7' };
const fmtDate = iso => { if (!iso) return ''; const [y, m, dd] = iso.split('-'); return `${dd}-${m}-${y}`; };
const td = 'padding:8px 10px;border-bottom:1px solid #eaecf0;vertical-align:top;font-size:13px;';
const th = 'padding:8px 10px;background:#f9fafb;border-bottom:1px solid #eaecf0;text-align:left;font-size:12px;color:#475467;';

const tile = (n, t, c) => `<td style="padding:12px 14px;border:1px solid #eaecf0;border-radius:8px;text-align:center;width:25%">
  <div style="font-size:24px;font-weight:700;color:${c}">${n}</div><div style="font-size:12px;color:#475467">${t}</div></td>`;

const rows = d.findings.map(f => `<tr>
  <td style="${td}"><span style="background:${bg[f.severity]};color:${colour[f.severity]};padding:2px 8px;border-radius:10px;font-size:12px;font-weight:600">${f.severity}</span></td>
  <td style="${td}"><b>${esc(label(f.rule))}</b><br><span style="color:#667085;font-size:11px">${f.detector === 'AI' ? 'AI review' : 'Rule check'}</span></td>
  <td style="${td}">${esc(f.client || '-')}<br><span style="color:#667085">${esc(f.task_id || '')} ${esc(f.task || '')}</span></td>
  <td style="${td}">${esc(f.staff || '-')}${f.date ? '<br><span style="color:#667085">' + fmtDate(f.date) + '</span>' : ''}</td>
  <td style="${td}">${esc(f.detail)}</td></tr>`).join('');

const wl = d.workload.map(w => {
  const c = w.utilisation_pct > 100 ? '#b42318' : w.utilisation_pct < 30 ? '#067647' : '#344054';
  return `<tr><td style="${td}">${esc(w.staff)}<br><span style="color:#667085">${esc(w.role)}</span></td>
  <td style="${td}text-align:right">${w.due_next_period_hrs}</td><td style="${td}text-align:right">${w.capacity_hrs}</td>
  <td style="${td}text-align:right;color:${c};font-weight:600">${w.utilisation_pct}%</td>
  <td style="${td}text-align:right">${w.spare_hrs}</td></tr>`; }).join('');

const cl = d.clientSummary.map(c => `<tr><td style="${td}">${esc(c.client)}</td>
  <td style="${td}text-align:right">${c.budget_hrs}</td><td style="${td}text-align:right">${c.actual_hrs}</td>
  <td style="${td}text-align:right;${c.pct > 100 ? 'color:#b42318;font-weight:600' : ''}">${c.pct}%</td></tr>`).join('');

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:900px;margin:auto;color:#101828">
<div style="background:#1f4e78;color:#fff;padding:18px 22px;border-radius:8px 8px 0 0">
  <div style="font-size:20px;font-weight:700">Practice Watchdog: Daily Partner Digest</div>
  <div style="font-size:13px;opacity:.85">${esc(cfg.firmName)} · as of ${fmtDate(d.asOfDate)} · look-ahead to ${fmtDate(d.horizonEnd)}</div>
</div>
<div style="padding:18px 22px;border:1px solid #eaecf0;border-top:0">
<table style="width:100%;border-collapse:separate;border-spacing:8px"><tr>
${tile(d.counts.high, 'High priority', '#b42318')}${tile(d.counts.medium, 'Medium', '#b54708')}${tile(d.counts.low, 'Low', '#475467')}${tile(d.stats.openTasks + ' / ' + d.stats.tasks, 'Open tasks', '#1f4e78')}
</tr></table>
<h3 style="margin:18px 0 6px">AI briefing</h3>
<div style="font-size:14px;line-height:1.5">${brief}</div>
${d.aiError ? `<p style="color:#b54708;font-size:13px">${esc(d.aiError)}</p>` : ''}
<h3 style="margin:22px 0 6px">All findings (${d.counts.total}: ${d.counts.rule} rule checks, ${d.counts.ai} AI review)</h3>
<table style="width:100%;border-collapse:collapse"><tr><th style="${th}">Priority</th><th style="${th}">Issue</th><th style="${th}">Client / task</th><th style="${th}">Staff / date</th><th style="${th}">Detail</th></tr>${rows}</table>
<h3 style="margin:22px 0 6px">Workload for the next ${cfg.thresholds.dueSoonDays} days</h3>
<table style="width:100%;border-collapse:collapse"><tr><th style="${th}">Staff</th><th style="${th}text-align:right">Hrs due</th><th style="${th}text-align:right">Capacity</th><th style="${th}text-align:right">Load</th><th style="${th}text-align:right">Spare hrs</th></tr>${wl}</table>
<h3 style="margin:22px 0 6px">Client budget vs actual (hours)</h3>
<table style="width:100%;border-collapse:collapse"><tr><th style="${th}">Client</th><th style="${th}text-align:right">Budget</th><th style="${th}text-align:right">Actual</th><th style="${th}text-align:right">Used</th></tr>${cl}</table>
<p style="font-size:11px;color:#667085;margin-top:22px;line-height:1.5">
Generated automatically from the practice-software export (${d.stats.timesheetEntries} timesheet entries, ${d.stats.totalHours} hrs).
Rule checks are deterministic; items marked "AI review" and the briefing are AI-generated and must be verified by the partner before any action is taken.
Only work-related records (tasks, timesheets, filing acknowledgements) are processed. Staff are informed of this monitoring and can see their own data, in line with the Digital Personal Data Protection Act, 2023.</p>
</div></div>`;

const subject = `Practice Watchdog ${fmtDate(d.asOfDate)}: ${d.counts.high} high-priority, ${d.counts.medium} medium issues`;
return [{ json: { to: cfg.partnerEmail, subject, html } }];
